const MODELS = {
  dual:   {name:'FD300',     mode:'dual', bedD:300, maxH:300, noz:['0.4','0.6'],       geo:{pe:337.265, arm:334.54, R:155.8}},
  FD300P: {name:'FD300 Pro', mode:'dual', bedD:300, maxH:270, noz:['0.4','0.6'],       geo:{pe:341.157, arm:336.76, R:175.5}},
  FD450P: {name:'FD450 Pro', mode:'dual', bedD:450, maxH:600, noz:['0.4','0.6','1.0'], geo:{pe:714.57,  arm:520,    R:266.24}},
  FD600P: {name:'FD600 Pro', mode:'dual', bedD:600, maxH:580, noz:['0.4','0.6','1.0'], geo:{pe:685.398, arm:634.1,  R:318.31}},
  FD800P: {name:'FD800 Pro', mode:'dual', bedD:800, maxH:600, noz:['0.4','0.6','1.0'], geo:{pe:728.66,  arm:986.5,  R:534.86}},
  quad:   {name:'FF600',     mode:'quad', bedD:600, maxH:580, noz:['0.4','0.6','1.0'], geo:{pe:647.91,  arm:634.9,  R:318.99}},
  FF800:  {name:'FF800',     mode:'quad', bedD:800, maxH:600, noz:['0.4','0.6','1.0'], geo:{pe:730.262, arm:988,    R:535.3}},
  dualUnknown:{like:'FD300P', mode:'dual', unknown:true},    /* 不確定是哪台＝照同料數最小的那台算 */
  quadUnknown:{like:'quad',   mode:'quad', unknown:true}
};
const LAYER = { dual:{'0.4':0.2,'0.6':0.3,'1.0':0.5}, quad:{'0.4':0.25,'0.6':0.35,'1.0':0.45} };   // 照片磚製程層高（T065 製程設定實查）
const TOWER = { size:35, gap:15, brim:8 };   // 循環洗料塔：index.html cycle sizeMm 35／gapMm 15／brimMm 8；PingCycleTower.cpp 先擺右邊、放不下改後面
const BASE_THICK = 10, THICK_RATIO = 15, THICK_MAX = 40, W_MARGIN = 50, SIZE_MIN = 20;
function M(){ const m=MODELS[S.model]; return m.like ? MODELS[m.like] : m; }
function modelLabel(){ return MODELS[S.model].unknown ? '不確定是哪台，先照最小的 '+M().name+' 算' : M().name+' 同進照片磚'; }
function capW(){ return M().bedD - W_MARGIN; }
function limitZ(g){ return g.pe + Math.sqrt(g.arm*g.arm - g.R*g.R) - g.arm; }
/* Klipper delta.py check_move：Z ≤ limit_z 整個盤面都搆得到；超過之後可達半徑＝R − √(arm² − (arm − 超出量)²) */
function reachAt(z, mdl){ const g=mdl.geo, bedR=mdl.bedD/2, lz=limitZ(g); if(z<=lz) return bedR;
  const a=z-lz; if(a>=g.arm) return 0; return Math.max(0, Math.min(bedR, g.R - Math.sqrt(g.arm*g.arm - (g.arm-a)*(g.arm-a)))); }
/* 磚置中；循環塔照 C++：先試右邊（用盤面外框判斷），放不下改後面。磚角與塔身角都要在頂端搆得到。 */
function fitsAt(W, H, T, mdl, rule){
  mdl = mdl || M();
  if(W > mdl.bedD - W_MARGIN + 1e-6) return {ok:false, why:'w'};
  if(H > mdl.maxH + 1e-6) return {ok:false, why:'h'};
  const r=reachAt(H, mdl), bedR=mdl.bedD/2;
  if(Math.hypot(W/2, T/2) > r + 1e-6) return {ok:false, why:'top'};
  const half=TOWER.size/2+TOWER.brim, off=TOWER.gap+TOWER.brim+TOWER.size/2, b=TOWER.size/2;
  let beside = (W/2+off+half) <= bedR;
  /* 第二輪 Q13（v4 實測抓到）：現行 C++ 只在「盤面放不下」才把塔改擺後面，沒考慮越往上搆得到的圈越小——
     很高的磚在大機上，右邊的塔頂端會搆不到（機台報超出範圍停機）。建議＝右邊頂端搆不到也改擺後面（要改 PingCycleTower.cpp）。 */
  if(beside && (rule||S.towerRule)==='reach' && Math.hypot(W/2+off+b, b) > r + 1e-6) beside=false;
  const cx = beside ? W/2+off : 0, cy = beside ? 0 : T/2+off;
  if(Math.hypot(Math.abs(cx)+b, Math.abs(cy)+b) > r + 1e-6) return {ok:false, why:'tower'};
  return {ok:true, beside};
}
function thickFloor(H){ return Math.min(THICK_MAX, Math.max(BASE_THICK, Math.ceil(H/THICK_RATIO*2)/2)); }
function thickOf(H){ return S.thickManual ? S.thick : thickFloor(H); }
function syncThick(){ if(!S.thickManual) S.thick=thickFloor(tileH()); }
/* 比例鎖住（寬高一起動）時這個比例最寬到多少：從上限往下找第一個印得到頂的整數寬度 */
function maxWLocked(asp, mdl){ mdl=mdl||M(); let w=Math.floor(Math.min(mdl.bedD-W_MARGIN, mdl.maxH*asp)+1e-9);
  for(; w>SIZE_MIN; w--){ const h=w/asp; if(fitsAt(w,h,thickOf(h),mdl).ok) return w; } return SIZE_MIN; }
function maxWFree(H, mdl){ mdl=mdl||M(); let w=Math.floor(mdl.bedD-W_MARGIN);
  for(; w>SIZE_MIN; w--){ if(fitsAt(w,H,thickOf(H),mdl).ok) return w; } return SIZE_MIN; }
function maxHFree(W, mdl){ mdl=mdl||M(); let h=Math.floor(mdl.maxH);
  for(; h>SIZE_MIN; h--){ if(fitsAt(W,h,thickOf(h),mdl).ok) return h; } return SIZE_MIN; }
function curAsp(){ return S.tileW / tileH(); }
function maxWNow(){ return S.lock ? maxWLocked(curAsp()) : maxWFree(tileH()); }
/* 高到這台上限時最寬多少（delta 越往上搆得到的圈越小；只有這一條會比「直徑 −50」更窄） */
function widestAtTop(mdl, rule){ const cw=mdl.bedD-W_MARGIN; for(let w=cw; w>SIZE_MIN; w--){ if(fitsAt(w,mdl.maxH,thickFloor(mdl.maxH),mdl,rule).ok) return w; } return SIZE_MIN; }
